using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class SpecialTests
{
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception("SPECIAL FAIL: "+name);checks++;Console.WriteLine("SPECIAL PASS: "+name);}static bool Near(double a,double b)=>Math.Abs(a-b)<.02;
 static string Hull(SpecialDefinition d)=>d.Roles.StartsWith("Titan")?"titan":d.Roles.Split(',')[0] switch{"CovertOps"=>"covert","ForceRecon"=>"recon","BlackOps"=>"blackops","Industrial"=>"hauler","Dread"=>"dread","ForceAux"=>"forceaux","Marauder"=>"marauder","MiningTender"=>"mining_tender","ExpeditionCommand"=>"expedition_command","CapitalIndustrial"=>"industrial_cap","Supercarrier"=>"supercarrier","Carrier"=>"carrier","HeavyInterdictor"=>"hic",_=>"recon"};
 static DemoWorld W(string hull){var w=new DemoWorld();w.NewGame(1);w.SpecialTrial(hull);w.Player.UtilityFit="";w.Player.Missiles=0;w.Player.Ore=0;w.CargoItems.Clear();w.Credits=1000000;return w;}
 static SpecialState Install(DemoWorld w,SpecialDefinition d,int i=0){if(d.Kind=="Phenomena")w.TitanAffinity=d.Roles[5..];Check(w.FitSpecial(d.Id,true,i),"Fit "+d.Name);return w.Player.Special[i];}
 static void Fuel(DemoWorld w,SpecialDefinition d){if(d.Fuel.Length>0)w.CargoItems[d.Fuel]=d.FuelQuantity*3;w.Player.Cap=w.Player.MaxCap;}
 public static void Run(){checks=0;Check(SpecialCatalog.All.Length==25,"25 unique functional profiles");Check(SpecialCatalog.All.Select(d=>d.ReferenceTypeId).Distinct().Count()==25,"25 distinct reference mappings");foreach(var d in SpecialCatalog.All){var w=W(Hull(d));float stock=w.ItemCount(d.Id,true);var s=Install(w,d);Check(w.ItemCount(d.Id,true)==stock-1,d.Name+" consumes module stock");Check(w.TotalFitCpu>=d.Cpu&&w.TotalFitPower>=d.Power,d.Name+" shared fitting load");Check(!w.ToggleSpecial(0),d.Name+" station activation rejected");Check(w.SetSpecialOnline(0,false)&&!s.Effective,d.Name+" offline");Check(w.SetSpecialOnline(0,true)&&s.Effective,d.Name+" online");Check(!w.FitSpecial(d.Id,true,8),d.Name+" invalid socket rejected");w.EnterSpecialRange();Fuel(w,d);if(d.Kind=="Panic")w.SelectedId=w.LockedId="special_rock";if(d.Kind=="Entosis")w.SelectedId=w.LockedId="relay_"+w.SystemId;if(d.Portal){var b=new JumpBeacon{System=DemoWorld.Systems.Last().Id,Kind=d.Kind=="CovertPortal"?"CovertCyno":d.Kind=="IndustrialPortal"?"IndustrialCyno":"Cyno"};w.JumpBeacons.Add(b);w.JumpBeaconSelection=b.Id;}float cap=w.Player.Cap,fuel=w.ItemCount(d.Fuel.Length>0?d.Fuel:"ore",false);Check(w.ToggleSpecial(0),d.Name+" activates / "+w.SpecialActivationError(0));Check(Near(w.Player.Cap,cap-d.Capacitor),d.Name+" pays capacitor once");if(d.Fuel.Length>0)Check(Near(w.ItemCount(d.Fuel,false),fuel-d.FuelQuantity),d.Name+" consumes real cycle fuel");if(d.WarpLock)Check(w.WarpBlocked("player")&&!w.CanDockAtStructure("player"),d.Name+" warp and dock interlocks");if(d.Immobile)Check(w.SpecialImmobile&&w.Player.Velocity==Vector3.Zero,d.Name+" immobilizes");if(d.Mode)Check(w.Player.Stat("remoteRepairImpedance")==0&&w.Player.Stat("remoteCapacitorImpedance")==0,d.Name+" remote repair and cap excluded");w.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.Player.Special[0].Active&&loaded.Player.Special[0].ModuleId==d.Id,d.Name+" active state save/load");if(d.Committed){w.ToggleSpecial(0);Check(s.Active&&s.StopRequested,d.Name+" cannot interrupt cycle");w.UpdateSpecial(s.CycleLeft+.001f);Check(!s.Active,d.Name+" stops at boundary");}else{w.ToggleSpecial(0);Check(!s.Active,d.Name+" stops");}w.Screen=ViewMode.Station;Check(w.UnfitSpecial(0)&&w.ItemCount(d.Id,true)==stock,d.Name+" module returned");}
 var cloak=W("recon");Install(cloak,SpecialCatalog.ById["sp_veil"]);double resolution=cloak.Player.Attributes["scanResolution"]!.Value;Check(cloak.Player.Stat("scanResolution")<resolution,"Standard cloak passive online scan penalty");cloak.EnterSpecialRange();cloak.ToggleSpecial(0);Check(cloak.Cloaked&&cloak.WarpBlocked("player"),"Standard cloak blocks warp");cloak.SelectedId="special_rock";cloak.LockTarget();Check(cloak.LockedId.Length==0,"Cloak blocks resource targeting");cloak.Player.Position=cloak.Targets[0].Position;cloak.UpdateSpecial(.1f);Check(!cloak.Cloaked&&cloak.SpecialLockRecovery>0&&cloak.Player.Special[0].Cooldown>0,"Proximity decloak, recovery and reactivation");Check(!cloak.ToggleSpecial(0),"Cloak reactivation denied during cooldown");
 var covert=W("covert");Install(covert,SpecialCatalog.ById["sp_ghost"]);covert.EnterSpecialRange();covert.ToggleSpecial(0);Check(covert.Cloaked&&!covert.WarpBlocked("player"),"Covert cloak supports warp");covert.EnterGrid("belt",false);Check(covert.Cloaked,"Covert cloak retained across warp");var wrong=W("blackops");Check(!wrong.FitSpecial("sp_ghost",true,0),"Black operations hull cannot fit covert warp cloak");var locked=W("recon");Install(locked,SpecialCatalog.ById["sp_veil"]);locked.EnterSpecialRange();locked.Targets.Add(new(){Id="hunter",Kind=TargetKind.Raider,Profile=new Ship(),Hull=100,LockId="player",Position=new(6000,0,0)});Check(!locked.ToggleSpecial(0),"Enemy lock blocks cloaking");
 foreach(string id in new[]{"sp_siege","sp_triage","sp_bastion","sp_core_m","sp_core_l","sp_core_c"}){var d=SpecialCatalog.ById[id];var w=W(Hull(d));Install(w,d);w.EnterSpecialRange();Fuel(w,d);double mass=w.Player.Stat("mass");w.ToggleSpecial(0);if(d.Kind!="Bastion")Check(w.Player.Stat("mass")>mass*5,id+" deployment mass increase");Check(w.Player.SpecialFactor("localRepair")>1&&w.Player.RepairCadence(d.Kind=="Core"?"ShieldBoost":"ArmorRepair",4)<1,id+" local repair amount and cycle");Check(w.Player.SpecialEcmImmune==(d.Kind!="Bastion"),id+" ECM immunity distinction");if(d.Kind=="Siege")Check(w.Player.SpecialWeapon(WeaponCatalog.All.First(w=>w.Size==4&&w.UsesTurret),"damage")>5,"Siege real turret damage modifier");if(d.Kind=="Triage")Check(w.Player.SpecialFactor("droneDamage")==0&&w.SpecialEwarBlocked&&w.Player.SpecialFactor("remoteAmount")>4,"Triage drone and hostile EWAR exclusion / remote bonus");if(d.Kind=="Bastion")Check(w.Player.Resistance("shield",DamageType.EM)>0&&w.Player.SpecialFactor("weaponCycle")<1,"Bastion resistance and weapon cadence");if(d.Kind=="Core")Check(w.IndustrialCore&&w.CoreLeft>0&&w.Player.SpecialFactor("droneMining")>1,"Fitted core drives compression state and mining drones");}
 var campaign=W("mining_tender");campaign.WeaponTestMode=false;campaign.EnterGrid("belt",false);campaign.CargoItems["ut_coolant"]=100;Check(!campaign.ToggleIndustrialCore(),"Campaign requires a fitted industrial core");
 var isa=W("carrier");Install(isa,SpecialCatalog.ById["sp_isa"]);isa.EnterSpecialRange();isa.ToggleSpecial(0);Check(isa.WarpBlocked("player")&&isa.CanUseMicroDrive("player")&&isa.Player.Stat("maxTargetRange")>1000000,"Integrated array blocks warp but permits micro-jump");var nsa=W("supercarrier");Install(nsa,SpecialCatalog.ById["sp_nsa"]);nsa.EnterSpecialRange();nsa.ToggleSpecial(0);Check(!nsa.CanUseMicroDrive("player")&&nsa.SpecialEwarBlocked,"Networked array blocks micro-jump and EWAR");Check(!W("carrier").FitSpecial("sp_nsa",true,0),"Networked array restricted to supercarriers");
 var relay=W("recon");Install(relay,SpecialCatalog.ById["sp_entosis"]);relay.EnterSpecialRange();relay.SelectedId=relay.LockedId="relay_"+relay.SystemId;Fuel(relay,SpecialCatalog.ById["sp_entosis"]);relay.CargoItems["sp_catalyst"]=10;relay.ToggleSpecial(0);relay.FinishSpecialTrialCycle();var node=relay.RelayNodes.First();Check(node.Progress==0&&relay.Player.Special[0].Warmed,"Relay first cycle warms up");relay.FinishSpecialTrialCycle();Check(node.Progress==.25f,"Relay subsequent cycle captures");node.Contested=true;relay.FinishSpecialTrialCycle();Check(node.Progress==.25f,"Opposing relay pauses capture");node.Contested=false;for(int i=0;i<3;i++)relay.FinishSpecialTrialCycle();Check(node.Owner=="Syndicate"&&node.Progress==1,"Four unopposed cycles capture sovereignty");relay.LockedId="";relay.UpdateSpecial(.1f);Check(!relay.Player.Special[0].Active&&!relay.Player.Special[0].Warmed,"Losing relay lock resets warmup");
 var massW=W("hic");Install(massW,SpecialCatalog.ById["sp_mass"]);massW.EnterSpecialRange();massW.SelectedId=massW.Wormholes[0].Id;massW.Player.Position=massW.Selected!.Position;double original=massW.Player.Stat("mass");Check(!massW.UseWormhole(),"Heavy hull exceeds frigate fracture mass");massW.ToggleSpecial(0);Check(massW.Player.Stat("mass")<original*.3&&massW.WarpBlocked("player"),"Nullmass reduces transit mass and locks warp");double budget=massW.Wormholes[0].RemainingMass;Check(massW.UseWormhole()&&massW.Wormholes[0].RemainingMass<budget,"Reduced mass consumes fracture budget on transit");massW.SelectedId=massW.Wormholes[0].Id;Check(massW.UseWormhole(),"Return fracture transit");massW.SelectedId=massW.Wormholes[0].Id;Check(!massW.UseWormhole(),"Third immediate fracture transit polarized");
 foreach(string id in new[]{"sp_phen_a","sp_phen_b","sp_phen_c","sp_phen_d"}){var d=SpecialCatalog.ById[id];var w=W("titan");Install(w,d);w.EnterSpecialRange();var p=new Ship();w.Targets.Add(new(){Id="foe",Kind=TargetKind.Raider,Profile=p,Shield=p.MaxShield*.5f,Armor=p.MaxArmor*.5f,Hull=p.MaxHull,Position=new(10000,0,0)});Fuel(w,d);w.ToggleSpecial(0);var t=w.Targets.Last();Check(t.Profile!.SpecialEnvironment.Count==d.Bonuses.Count,id+" affects hostile ships");Check(Near(t.Shield/t.Profile.MaxShield,.5)&&Near(t.Armor/t.Profile.MaxArmor,.5),id+" preserves health fractions");Check(w.Player.SpecialFactor(d.Bonuses.Keys.First())==1+d.Bonuses.Values.First(),id+" strongest aura applied once");t.Position=new(d.Range+100,0,0);w.UpdateSpecial(.1f);Check(t.Profile.SpecialEnvironment.Count==0,id+" leaving radius clears effects");}
 var panic=W("industrial_cap");Install(panic,SpecialCatalog.ById["sp_panic"]);panic.EnterSpecialRange();Check(!panic.ToggleSpecial(0),"Nexus requires asteroid lock");panic.LockedId=panic.SelectedId="special_rock";Check(panic.ToggleSpecial(0)&&panic.Player.NexusLeft>0&&panic.SpecialOffenseBlocked,"Nexus invulnerability and offensive exclusion");panic.Player.Special[1]=new(){ModuleId="sp_industrial_portal"};panic.JumpBeacons.Add(new(){System=DemoWorld.Systems.Last().Id,Kind="IndustrialCyno"});panic.JumpBeaconSelection=panic.JumpBeacons.Last().Id;Check(!panic.ToggleSpecial(1),"Nexus blocks opening a conduit bridge");panic.ToggleSpecial(0);Check(panic.Player.Special[0].Active,"Nexus cannot cancel early");
 ExtendedChecks();CloneChecks();BridgeChecks();Console.WriteLine($"{checks} special capital simulation checks passed.");}
 static void ExtendedChecks(){
 var cd=W("recon");Install(cd,SpecialCatalog.ById["sp_veil"]);cd.EnterSpecialRange();cd.ToggleSpecial(0);cd.ToggleSpecial(0);cd.Screen=ViewMode.Station;cd.UnfitSpecial(0);Check(cd.FitSpecial("sp_veil",true,0)&&cd.Player.Special[0].Cooldown>0,"Unfit and refit preserve cloak cooldown");cd.UnfitSpecial(0);Check(cd.TransferItem("sp_veil",true,1)&&cd.FitSpecial("sp_veil",false,0)&&cd.Player.Special[0].Cooldown>0,"Cargo transfer preserves capital cooldown");
 var fleet=W("blackops");fleet.HireWingmate("Escort");Check(fleet.AssignFleetHull(fleet.Wingmates[0].Id,"covert")&&fleet.Wingmates[0].HullId=="covert","Docked fleet hull assignment for bridge eligibility");var core=W("mining_tender");Install(core,SpecialCatalog.ById["sp_core_m"]);var condenser=UtilityCatalog.All.First(d=>d.Kind=="Compress"&&d.Role=="MiningTender"&&d.Family=="Asteroid Ore");Check(core.FitUtility(condenser.Id,true,0),"Fitted core and condenser share high sockets");core.StowSpecialFuel();Check(core.ItemCount("ut_coolant",false)>=SpecialCatalog.ById["sp_core_m"].FuelQuantity,"Fuel loader prioritizes fitted industrial core");core.EnterSpecialRange();core.Player.Ore=100;Check(core.ToggleIndustrialCore()&&core.ToggleUtility(0)&&core.CompressUtility("ore",100)&&core.ItemCount("compressed_ore",false)==100,"Fitted core enables real lossless compression");core.ToggleIndustrialCore();core.UpdateSpecial(core.CoreLeft+.01f);Check(!core.IndustrialCore&&!core.Player.Utilities[0].Active,"Fitted core boundary stops compression service");
 var siege=W("dread");Install(siege,SpecialCatalog.ById["sp_siege"]);siege.EnterSpecialRange();Fuel(siege,SpecialCatalog.ById["sp_siege"]);siege.ToggleSpecial(0);siege.EwarEffects.Add(new(){SourceId="player",TargetId="player",Kind=EwarKind.ECM,Remaining=20,Strength=1});Check(siege.Player.LocalModeFactor("localRepair","ShieldBoost",1)==1&&siege.Player.LocalModeFactor("localRepair","ShieldBoost",4)>1,"Siege bonus applies only to capital local repair modules");Check(siege.Player.SpecialWeapon(WeaponCatalog.Get("rail"),"damage")==1,"Siege does not multiply subcapital turret damage");Check(siege.EwarFor("player").Jammers.Length==0,"Siege actually ignores ECM snapshots");
 var aura=W("titan");Check(!aura.FitSpecial("sp_phen_b",true,0)&&aura.ConfigureTitanAffinity("Boreal")&&aura.FitSpecial("sp_phen_b",true,0),"Faction-specific phenomena fitting and affinity control");Check(!aura.ConfigureTitanAffinity("Aurora"),"Cannot change faction around a fitted phenomena module");
 var pulse=W("covert");Install(pulse,SpecialCatalog.ById["sp_ghost"]);pulse.EnterSpecialRange();pulse.ToggleSpecial(0);pulse.CloakObservatoryPulse();Check(pulse.Cloaked,"New cloak protected from observatory pulse");pulse.Player.Special[0].ActiveSeconds=901;for(int i=0;i<20&&pulse.Cloaked;i++)pulse.CloakObservatoryPulse();Check(!pulse.Cloaked,"Unstabilized cloak vulnerable to observatory pulse");
 var fatigue=W("blackops");fatigue.EnterSpecialRange();fatigue.CargoItems["jump_fuel"]=5000;fatigue.JumpFatigue=1000;Check(fatigue.JumpToBeacon(DemoWorld.Systems.Last().Id)&&fatigue.JumpDriveCooldown>60,"Accumulated fatigue increases jump reactivation");
 }
 static void CloneChecks(){var w=W("supercarrier");Install(w,SpecialCatalog.ById["sp_recloner"]);w.HireWingmate("Escort");var pilot=w.Wingmates[0];w.Hangar["sp_mapper"]=2;Check(w.MapFleetPilot(pilot.Id)&&w.MappedPilots[pilot.Id]==21600,"Mapper consumes six-hour mapping charge");Check(w.StoreRecloneShip("cruiser"),"Reserve ship purchase");w.CargoItems["sp_clonefuel"]=20;w.EnterSpecialRange();w.ToggleSpecial(0);Check(w.SimulateMappedPilotLoss(pilot.Id)&&pilot.Hull>0&&w.RecloneShips["cruiser"]==0&&w.ItemCount("sp_clonefuel",false)==10,"Tactical reclone consumes mapping, fitted reserve and fuel");w.SimulateMappedPilotLoss(pilot.Id);Check(pilot.Hull==0,"No free recloning without reserve/mapping");var vat=W("titan");Install(vat,SpecialCatalog.ById["sp_vat"]);vat.HireWingmate("Escort");vat.EnterSpecialRange();Fuel(vat,SpecialCatalog.ById["sp_vat"]);vat.ToggleSpecial(0);Check(!vat.InstallJumpClone()&&vat.InstallJumpClone(vat.Wingmates[0].Id),"Mobile nursery clones other fleet pilots");var c=W("recon");Check(c.InstallJumpClone(),"Station jump clone installation");string origin=c.SystemId;c.JumpClones[0].System=DemoWorld.Systems.Last().Id;c.CargoItems["sp_mapper"]=2;Check(c.JumpToClone(c.JumpClones[0].Id)&&c.ParkedShips[0].System==origin&&c.ParkedShips[0].Cargo["sp_mapper"]==2&&c.Player.CombatHull=="frigate","Clone jump parks actual fitted ship and cargo");c.Save();var l=new DemoWorld();Check(l.Load()&&l.ParkedShips.Count==1&&l.CloneJumpCooldown>0,"Parked clone ship and cooldown persist");}
 static void BridgeChecks(){var w=W("blackops");Install(w,SpecialCatalog.ById["sp_covert_portal"]);w.HireWingmate("Escort");w.Wingmates[0].HullId="covert";string dest=DemoWorld.Systems.Last().Id;Check(w.ContractJumpBeacon(dest,"CovertCyno"),"Contract purchases finite remote beacon");w.CargoItems["jump_fuel"]=5000;w.EnterSpecialRange();w.ToggleSpecial(0);string origin=w.SystemId;Check(w.BridgeSpecial(false)&&w.SystemId==origin&&w.LastBridgePassengers==1&&w.Wingmates[0].System==dest,"Bridge moves fleet without anchor");w.UpdateMobility(w.JumpDriveCooldown+1);w.JumpBeacons[0].Left=100;w.Player.Cap=w.Player.MaxCap;Check(w.BridgeSpecial(true)&&w.SystemId==dest,"Conduit transfers anchor");var expired=W("dread");expired.WeaponTestMode=false;expired.EnterGrid("belt",false);expired.CargoItems["jump_fuel"]=5000;Check(expired.JumpDriveError(dest).Contains("live"),"Campaign jump requires live beacon");}
